#include "content/ContentTemplateGate.hpp"
namespace elysium::content {void TemplateGate::addKnown(ContentId id){if(id)known_.insert(id);}ContentId TemplateGate::idOf(const TemplateRecord&r)const{return r.kind==TemplateKind::Creature?r.creature.id:r.kind==TemplateKind::Poi?r.poi.id:r.machine.id;}bool TemplateGate::add(TemplateRecord r){auto id=idOf(r);if(frozen_||!id||records_.contains(id))return false;records_[id]=std::move(r);return true;}bool TemplateGate::advance(ContentId id,Workflow w){auto i=records_.find(id);if(i==records_.end()||unsigned(w)!=unsigned(i->second.workflow)+1)return false;if(!validate(id).empty())return false;i->second.workflow=w;return true;}std::vector<Validation>TemplateGate::validate(ContentId id)const{std::vector<Validation>o;auto i=records_.find(id);if(i==records_.end())return{{id,"missing_template"}};auto&r=i->second;if(r.schemaVersion!=1)o.push_back({id,"stale_schema_version"});auto req=[&](ContentId x,const char*c){if(!x)o.push_back({id,c});else if(!known_.contains(x))o.push_back({id,"missing_reference"});};if(r.kind==TemplateKind::Creature){auto&c=r.creature;req(c.faction,"missing_faction");req(c.bodyPlan,"missing_body_plan");req(c.ability,"missing_ability");req(c.telegraph,"missing_telegraph");req(c.dropTable,"missing_drop_table");req(c.spawnSignal,"missing_spawn_signal");req(c.aiProfile,"missing_ai_profile");if(c.silhouetteMeters<=0||c.healthBudget<=0||c.damageBudget<=0||c.speedBudget<=0)o.push_back({id,"invalid_creature_budget"});}else if(r.kind==TemplateKind::Poi){auto&q=r.poi;req(q.approachReason,"missing_approach_reason");req(q.silhouette,"missing_silhouette");req(q.entryState,"missing_entry_state");req(q.traversalHook,"missing_traversal_hook");req(q.rewardDomain,"missing_reward_domain");req(q.persistenceSchema,"missing_persistence_schema");req(q.faction,"missing_faction");if(!q.stableIdSlot||!q.tombstoneSlot)o.push_back({id,"missing_persistence_identity_slots"});for(auto x:q.variationModules)req(x,"missing_variation_module");}else{auto&m=r.machine;if(m.painAnswered.empty())o.push_back({id,"missing_pain_answered"});if(m.readableFailure.empty())o.push_back({id,"missing_readable_failure"});req(m.persistenceSchema,"missing_persistence_schema");req(m.presentationSchema,"missing_presentation_schema");for(auto x:m.inputs)req(x,"unobtainable_or_missing_input");for(auto x:m.outputs)req(x,"missing_output_reference");}return o;}std::vector<Validation>TemplateGate::validateAll()const{std::vector<Validation>o;for(auto&[id,r]:records_){auto v=validate(id);o.insert(o.end(),v.begin(),v.end());if(r.workflow!=Workflow::IntegrationReady)o.push_back({id,"incomplete_review_workflow"});}return o;}bool TemplateGate::freeze(){if(!validateAll().empty())return false;frozen_=true;return true;}}
